function thenable(value) {
  if (value && typeof value.then === 'function' && typeof value.catch === 'function') return value;
  const obj = {
    then: (resolve) => thenable(resolve ? resolve(value) : value),
    catch: (fn) => thenable(value),
  };
  if (value && typeof value === 'object' && !Array.isArray(value)) {
    Object.keys(value).forEach(key => {
      if (!(key in obj)) obj[key] = value[key];
    });
  }
  return obj;
}

class QueryBuilder {
  constructor(table) {
    this.table = table;
    this.filters = [];
    this.action = null;
    this.payload = null;
    this._head = false;
    this._count = false;
    this._limit = null;
    this._single = false;
    this._order = null;
    this._insertedRows = null;
  }

  select(cols, opts) {
    this.action = 'select';
    if (opts?.count === 'exact') { this._count = true; if (opts.head) this._head = true; }
    return this;
  }

  insert(data) {
    this.action = 'insert';
    this.payload = data;
    const result = this._execute();
    if (this.table === 'sales') {
      console.log('INSERT sale:', this._insertedRows);
    }
    result.select = () => {
      const rows = this._insertedRows || [];
      const sel = thenable({ data: rows, error: null });
      sel.single = () => thenable({ data: rows[0] || null, error: null });
      return sel;
    };
    if (this._insertedRows) {
      result.single = () => thenable({ data: this._insertedRows[0] || null, error: null });
    }
    return result;
  }

  update(data) {
    this.action = 'update';
    this.payload = data;
    return this;
  }

  delete() {
    this.action = 'delete';
    return this;
  }

  upsert(data) {
    this.action = 'upsert';
    this.payload = data;
    return this._execute();
  }

  eq(col, val) { this.filters.push({ type: 'eq', col, val }); return this; }
  gte(col, val) { this.filters.push({ type: 'gte', col, val }); return this; }
  lte(col, val) { this.filters.push({ type: 'lte', col, val }); return this; }
  not(col, val) { this.filters.push({ type: 'not', col, val }); return this; }
  is(col, val) { this.filters.push({ type: 'is', col, val }); return this; }
  in(col, vals) { this.filters.push({ type: 'in', col, vals }); return this; }

  order(col, opts = {}) {
    this._order = { col, ascending: opts.ascending !== false };
    return this;
  }

  limit(n) {
    this._limit = n;
    return this;
  }

  single() { this._single = true; return this._execute(); }
  maybeSingle() { return this.single(); }

  then(resolve) { resolve(this._execute()); }
  catch(fn) { return this; }

  _applyFilters(list) {
    return list.filter(r =>
      this.filters.every(f => {
        try {
          if (f.type === 'eq') return r[f.col] === f.val;
          if (f.type === 'gte') return new Date(r[f.col]) >= new Date(f.val);
          if (f.type === 'lte') return new Date(r[f.col]) <= new Date(f.val);
          if (f.type === 'not') return r[f.col] !== f.val;
          if (f.type === 'is') return r[f.col] === null || r[f.col] === undefined;
          if (f.type === 'in') return f.vals.includes(r[f.col]);
          return true;
        } catch { return false; }
      })
    );
  }

  _execute() {
    const rows = load(this.table);

    if (this.action === 'insert') {
      const arr = Array.isArray(this.payload) ? this.payload : [this.payload];
      const newRows = arr.map(d => {
        const base = { id: genID(), ...d };
        if (this.table === 'sales' && !base.invoice_number) {
          base.invoice_number = '' + (rows.length + 1);
        }
        return base;
      });
      save(this.table, [...rows, ...newRows]);
      this._insertedRows = newRows;
      return thenable({ data: newRows, error: null });
    }

    if (this.action === 'update') {
      try {
        const updated = rows.map(r =>
          this.filters.every(f => r[f.col] === f.val) ? { ...r, ...this.payload } : r
        );
        save(this.table, updated);
        return thenable({ error: null });
      } catch (e) { return thenable({ error: { message: e.message } }); }
    }

    if (this.action === 'delete') {
      try {
        const remaining = rows.filter(r => !this.filters.every(f => r[f.col] === f.val));
        save(this.table, remaining);
        return thenable({ error: null });
      } catch (e) { return thenable({ error: { message: e.message } }); }
    }

    if (this.action === 'upsert') {
      try {
        const updates = Array.isArray(this.payload) ? this.payload : [this.payload];
        updates.forEach(d => {
          const idx = rows.findIndex(r => r.id === d.id);
          if (idx >= 0) rows[idx] = d;
          else rows.push({ id: genID(), ...d });
        });
        save(this.table, rows);
        return thenable({ error: null });
      } catch (e) { return thenable({ error: { message: e.message } }); }
    }

    // select (or fallback)
    this.action = 'select';
    let list = this._applyFilters(rows);
    if (this._order) {
      const { col, ascending } = this._order;
      list.sort((a, b) => (a[col] > b[col] ? 1 : -1) * (ascending ? 1 : -1));
    }
    if (this._limit !== null) list = list.slice(0, this._limit);
    if (this._single) return thenable({ data: list[0] || null, error: null });
    if (this._count) {
      const total = this._applyFilters(rows).length;
      return thenable({ count: total, data: this._head ? [] : list, error: null });
    }
    return thenable({ data: list, error: null });
  }
}

function getStoredUser() {
  const raw = localStorage.getItem('local_user');
  return raw ? JSON.parse(raw) : null;
}

export const supabase = {
  from: (table) => new QueryBuilder(table),
  auth: {
    signInWithPassword: async ({ email, password }) => {
      const staff = load('staff');
      const user = staff.find(u => u.email === email && u.pin_code === password);
      if (!user) return { error: { message: 'Invalid credentials' } };
      localStorage.setItem('local_user', JSON.stringify(user));
      return { data: { user }, error: null };
    },
    signOut: async () => { localStorage.removeItem('local_user'); return { error: null }; },
    getSession: async () => {
      const user = getStoredUser();
      return { data: { session: user ? { user, access_token: 'offline', refresh_token: 'offline' } : null } };
    },
    onAuthStateChange: (cb) => {
      const user = getStoredUser();
      setTimeout(() => cb('SIGNED_IN', { user }), 10);
      return { data: { subscription: { unsubscribe: () => {} } } };
    },
    setSession: async () => ({ error: null }),
    signUp: async ({ email, password, options }) => {
      const staff = load('staff');
      const newUser = { id: genID(), email, pin_code: password, full_name: options?.data?.full_name || 'New User', role: 'cashier', is_active: true, store_id: null };
      save('staff', [...staff, newUser]);
      return { data: { user: newUser }, error: null };
    },
  },
  storage: {
    from: () => ({
      upload: async () => ({ error: null }),
      getPublicUrl: () => ({ data: { publicUrl: '' } }),
    }),
  },
  rpc: () => thenable({ error: null }),
};
